import sys
import random

seed = int(sys.stdin.readline())
rng = random.Random(seed)
n = rng.randint(1, 6)
m = rng.randint(1, 6)
g = []
for i in range(n):
    row = []
    for j in range(m):
        if rng.random() < 0.25:
            row.append(-1)
        else:
            row.append(rng.randint(0, 20))
    g.append(row)
if g[0][0] < 0:
    g[0][0] = rng.randint(0, 20)
if g[n - 1][m - 1] < 0:
    g[n - 1][m - 1] = rng.randint(0, 20)
print(n, m)
for row in g:
    print(' '.join(map(str, row)))
